sys_script_include.script:
var ServiceCatalogMarkdownGenerator = (function() {
    /** @type {ServiceCatalogMarkdownGeneratorConstructor} */
    ServiceCatalogMarkdownGeneratorConstructor = Class.create();

    /**
     * @param {(GlideRecord | GlideRecordSecure)} varGr - item_option_new
     * @param {string[]} markdownLines
     * @param {MarkdownGenerationContext} context
     * @param {string} [tableUrl]
     */
    function pushVariableDetailMarkdown(varGr, markdownLines, context) {
        markdownLines.push('');
        markdownLines.push("### Variable: " + varGr.getValue('name'));
        markdownLines.push('');

        if (varGr.getDisplayValue('map_to_field') == 'true') {
            markdownLines.push('- **' + MarkdownGenerationContext.escapeForMarkdown(varGr.map_to_field.getLabel()) + ':** True');
            markdownLines.push(context.getColumnReferenceMdLink(varGr.record_producer_table, varGr.field));
        }

        /** @type {tyLabeledMultilineStackItem[]} */
        var multiLineStack = [];
        context.pushDisplayValueListItem(varGr.type, markdownLines, multiLineStack);
        context.pushDisplayValueListItem(varGr.question_text, markdownLines, multiLineStack);
        context.pushDisplayValueListItem(varGr.conversational_label, markdownLines, multiLineStack);
        context.pushDisplayValueListItem(varGr.tooltip, markdownLines, multiLineStack);
        context.pushDisplayValueListItem(varGr.order, markdownLines, multiLineStack);
        context.pushListItemIfTrue(varGr.show_help, markdownLines);
        if (varGr.getDisplayValue('show_help') == 'true') {
            if (varGr.help_tag != 'More information')
                context.pushValueListItem(varGr.help_tag, markdownLines, multiLineStack);
            context.pushDisplayValueListItem(varGr.help_text, markdownLines, multiLineStack);
            context.pushCodeListItem(varGr.instructions, 'html', markdownLines, multiLineStack);
        }
        var listChoices = false;
        var type = parseInt(varGr.getValue('type'));
        switch (type) {
            case 1: // Yes / No
                context.pushListItemIfTrue(varGr.include_none, markdownLines);
                break;
            case 2: // Multi Line Text
                context.pushCodeListItem(varGr.attributes, 'text', markdownLines, multiLineStack);
                break;
            case 3: // Multiple Choice
                context.pushDisplayValueListItem(varGr.choice_direction, markdownLines, multiLineStack);
                context.pushListItemIfTrue(varGr.include_none, markdownLines);
                context.pushListItemIfTrue(varGr.do_not_select_first, markdownLines);
                context.pushCodeListItem(varGr.attributes, 'text', markdownLines, multiLineStack);
                listChoices = true;
                break;
            case 5: // Select Box
            case 18: // Lookup Select Box
                if (!gs.nil(varGr.choice_table)) {
                    context.pushTableReferenceListItem(varGr.choice_table, markdownLines);
                    context.pushFieldReferenceListItem(varGr.choice_table, varGr.choice_field, markdownLines);
                }
                context.pushListItemIfTrue(varGr.include_none, markdownLines);
                context.pushListItemIfTrue(varGr.lookup_unique, markdownLines);
                context.pushCodeListItem(varGr.attributes, 'text', markdownLines, multiLineStack);
                listChoices = true;
                break;
            case 8: // Reference
                context.pushTableReferenceListItem(varGr.reference, markdownLines);
                context.pushDisplayValueListItem(varGr.use_reference_qualifier, markdownLines, multiLineStack);
                switch (varGr.getValue('use_reference_qualifier')) {
                    case 'simple':
                        context.pushCodeListItem(varGr.reference_qual_condition, 'text', markdownLines, multiLineStack);
                        break;
                    default:
                        context.pushCodeListItem(varGr.reference_qual, 'text', markdownLines, multiLineStack);
                        break;
                }
                context.pushCodeListItem(varGr.attributes, 'text', markdownLines, multiLineStack);
                break;
            case 19: // Container Start
                context.pushListItemIfTrue(varGr.display_title, markdownLines);
                context.pushDisplayValueListItem(varGr.layout, markdownLines, multiLineStack);
                break;
            case 22: // Lookup Multiple Choice
                context.pushDisplayValueListItem(varGr.lookup_source, markdownLines, multiLineStack);
                switch (varGr.getValue('lookup_source')) {
                    case 'choice':
                    case 'choices':
                        if (!gs.nil(varGr.choice_table)) {
                            context.pushTableReferenceListItem(varGr.choice_table, markdownLines);
                            context.pushFieldReferenceListItem(varGr.choice_table, varGr.choice_field, markdownLines);
                        }
                        break;
                }
                context.pushDisplayValueListItem(varGr.choice_direction, markdownLines, multiLineStack);
                context.pushListItemIfTrue(varGr.include_none, markdownLines);
                context.pushListItemIfTrue(varGr.lookup_unique, markdownLines);
                context.pushValueListItem(varGr.reference_qual, markdownLines, multiLineStack);
                context.pushCodeListItem(varGr.attributes, 'text', markdownLines, multiLineStack);
                break;
            case 21: // List Collector
                context.pushTableReferenceListItem(varGr.list_table, markdownLines);
                context.pushDisplayValueListItem(varGr.use_reference_qualifier, markdownLines, multiLineStack);
                switch (varGr.getValue('use_reference_qualifier')) {
                    case 'simple':
                        context.pushCodeListItem(varGr.reference_qual_condition, 'text', markdownLines, multiLineStack);
                        break;
                    default:
                        context.pushCodeListItem(varGr.reference_qual, 'text', markdownLines, multiLineStack);
                        break;
                }
                context.pushCodeListItem(varGr.attributes, 'text', markdownLines, multiLineStack);
                break;
            case 4: // Numeric Scale
            case 6: // Single Line Text
            case 7: // CheckBox
            case 9: // Date
            case 10: // Date/Time
            case 11: // Label
            case 12: // Break
            case 14: // Custom
            case 15: // UI Page
            case 16: // Wide Single Line Text
            case 17: // Custom with Label
            case 20: // Container End
            case 23: // HTML
            case 24: // Container Split
            case 25: // Masked
            case 26: // Email
            case 27: // URL
            case 28: // IP Address
            case 29: // Duration
            case 31: // Requested For
            case 32: // Rich Text Label
            case 33: // Attachment
            case 40: // Table Name
                break;
            default:
                markdownLines.push("- **Unknown type:** *" + varGr.getValue('type') + '*');
                break;
        }

        context.pushListItemIfTrue(varGr.global, markdownLines);
        context.pushListItemIfTrue(varGr.disable_initial_slot_fill, markdownLines);
        context.pushDisplayValueListItem(varGr.variable_width, markdownLines, multiLineStack);
        context.pushListItemIfFalse(varGr.visible_standalone, markdownLines);
        context.pushListItemIfFalse(varGr.visible_bundle, markdownLines);
        context.pushListItemIfTrue(varGr.not_available_conversation, markdownLines);
        context.pushListItemIfFalse(varGr.visible_guide, markdownLines);
        context.pushListItemIfFalse(varGr.visible_summary, markdownLines);
        switch (type) {
            case 20: // Container End
            case 24: // Container Split
            case 32: // Rich Text Label
                break;
            case 19: // Container Start
                context.pushListItemIfTrue(varGr.hidden, markdownLines);
                break;
            default:
                context.pushListItemIfTrue(varGr.mandatory, markdownLines);
                if (!varGr.mandatory) {
                    context.pushListItemIfTrue(varGr.hidden, markdownLines);
                    context.pushListItemIfTrue(varGr.read_only, markdownLines);
                }
                break;
        }
        switch (type) {
            case 2: // Multi Line Text
            case 7: // CheckBox
            case 9: // Date
            case 10: // Date/Time
                context.pushCodeListItem(varGr.default_value, 'text', markdownLines, multiLineStack);
                break;
            case 1: // Yes / No
            case 3: // Multiple Choice
            case 4: // Numeric Scale
            case 6: // Single Line Text
            case 16: // Wide Single Line Text
            case 18: // Lookup Select Box
            case 26: // Email
            case 27: // URL
            case 28: // IP Address
            case 29: // Duration
            case 5: // Select Box
                context.pushCodeListItem(varGr.default_value, 'text', markdownLines, multiLineStack, true);
                break;
            case 23: // HTML
                if (gs.nil(varGr.default_html_value))
                    context.pushCodeListItem(varGr.default_value, 'text', markdownLines, multiLineStack, true);
                else
                    context.pushCodeListItem(varGr.default_html_value, 'html', markdownLines, multiLineStack, true);
                break;
            case 32: // Rich Text Label
                context.pushCodeListItem(varGr.rich_text, 'html', markdownLines, multiLineStack, true);
                break;
            case 19: // Container Start
            case 20: // Container End
            case 24: // Container Split
                break;
            default:
                context.pushDisplayValueListItem(varGr.default_value, markdownLines, multiLineStack);
                break;
        }

        context.pushDisplayValueListItem(varGr.example_text, markdownLines, multiLineStack);
        context.pushDisplayValueListItem(varGr.validate_regex, markdownLines, multiLineStack);
        context.pushDisplayValueListItem(varGr.roles_to_use_also_request_for, markdownLines, multiLineStack);
        context.pushMultiLineItems(multiLineStack, markdownLines);

        if (listChoices) {
            var choiceGr = new GlideRecord('question_choice');
            choiceGr.addQuery('question', varGr.sys_id);
            choiceGr.addQuery('inactive', false);
            choiceGr.orderBy('order');
            choiceGr.query();
            if (choiceGr.next()) {
                markdownLines.push('');
                markdownLines.push('**Choices:**');
                markdownLines.push('');
                markdownLines.push('| Label | Value | Sequence |');
                markdownLines.push('| ----- | ----- | -------- |');
                do {
                    markdownLines.push("| " + MarkdownGenerationContext.escapeForMarkdown(choiceGr.getValue('text'), true) + " | " + MarkdownGenerationContext.escapeForMarkdown(choiceGr.getValue('value'), true) + " | " + choiceGr.getDisplayValue('order') + " |");
                } while (choiceGr.next());
            }
        }
    }

    /**
     * @param {(GlideRecord | GlideRecordSecure)} varSetGr - item_option_new_set
     * @param {string} order
     * @param {string[]} markdownLines
     * @param {MarkdownGenerationContext} context
     */
    function pushVariableSetDetailMarkdown(varSetGr, order, markdownLines, context) {
        markdownLines.push('');
        markdownLines.push("### Variable Set: " + varSetGr.getValue('internal_name'));
        markdownLines.push('');

        markdownLines.push('- **Title:** [' + MarkdownGenerationContext.escapeForMarkdown(gs.nil(varSetGr.title) ? varSetGr.getValue('internal_name') : varSetGr.getValue('title')) + '](' + context.mapper.getVarSetUrl(varSetGr, context.getCurrentFolder()) + ')');
        markdownLines.push('- **Order:** ' + order);
        /** @type {tyLabeledMultilineStackItem[]} */
        var multiLineStack = [];
        context.pushDisplayValueListItem(varSetGr.type, markdownLines, multiLineStack);
        context.pushListItemIfTrue(varSetGr.display_title, markdownLines);
        context.pushDisplayValueListItem(varSetGr.layout, markdownLines, multiLineStack);
        context.pushDisplayValueListItem(varSetGr.description, markdownLines, multiLineStack);
        context.pushMultiLineItems(multiLineStack, markdownLines);
    }

    /**
     * @param {(GlideRecord | GlideRecordSecure)} catItemGr - sc_cat_item
     * @param {string[]} markdownLines
     * @param {MarkdownGenerationContext} context
     */
    function pushAvailabilitySection(catItemGr, markdownLines, context) {
        var catItemSysId = catItemGr.getUniqueValue();
        var availGr = new GlideRecord('sc_cat_item_user_criteria_mtom');
        availGr.addQuery('sc_cat_item', catItemSysId);
        availGr.orderBy('user_criteria.name');
        availGr.query();
        var notAvailGr = new GlideRecord('sc_cat_item_user_criteria_no_mtom');
        notAvailGr.addQuery('sc_cat_item', catItemSysId);
        notAvailGr.orderBy('user_criteria.name');
        notAvailGr.query();
        if (!(availGr.hasNext() || notAvailGr.hasNext()))
            return;

        markdownLines.push('', '## Availability');

        if (availGr.next()) {
            markdownLines.push('', '**Available for:**', '');
            do {
                markdownLines.push('- ' + MarkdownGenerationContext.escapeForMarkdown(availGr.getDisplayValue('user_criteria')));
            } while (availGr.next());
        }

        if (notAvailGr.next()) {
            markdownLines.push('', '**Not available for:**', '');
            do {
                markdownLines.push('- ' + MarkdownGenerationContext.escapeForMarkdown(notAvailGr.getDisplayValue('user_criteria')));
            } while (notAvailGr.next());
        }
    }

    /**
     * @typedef QuestionItemOld
     * @property {string} sys_id
     * @property {number} type_value
     * @property {string} type_label
     * @property {string} question_text
     * @property {string} name
     * @property {boolean} is_set
     * @property {({ display: string: value: number })} order
     */

    /**
     * @param {string} text
     * @returns {string}
     */
    function decodeCatalogConditions(text) {
        var re = /^([^^]+(?:\^(?!NQ)[^^]+)*)\^NQ ?/g;
        var iml = re.test(text);
        if (iml) {
            text = text.replace(re, "\n  - $1^EQ\n  - *OR:* ");
            text = text.replace(/\^NQ ?/g, "^EQ\n  - *OR:* ");
        }
        text = text.replace(/\s?ISNOTEMPTY\^EQ/g, ' is not empty');
        text = text.replace(/\s?ISNOTEMPTY\^\s?/g, ' is not empty **AND** ');
        text = text.replace(/\s?ISEMPTY\^EQ/g, ' is empty');
        text = text.replace(/\s?ISEMPTY\^\s?/g, ' is empty **AND** ');
        text = text.replace(/\s?NOT IN(\w+),(\w+),(\w+),(\w+)\^EQ/g, ' is not one of `$1`, `$2`, `$3`, `$4`');
        text = text.replace(/\s?NOT IN(\w+),(\w+),(\w+)\^EQ/g, ' is not one of `$1`, `$2`, `$3`');
        text = text.replace(/\s?NOT IN(\w+),(\w+)\^EQ/g, ' is not one of `$1`, `$2`');
        text = text.replace(/\s?NOT IN(\w+),(\w+),(\w+),(\w+)\^\s?/g, ' is not one of `$1`, `$2`, `$3`, `$4` **AND** ');
        text = text.replace(/\s?NOT IN(\w+),(\w+),(\w+)\^\s?/g, ' is not one of `$1`, `$2`, `$3` **AND** ');
        text = text.replace(/\s?NOT IN(\w+),(\w+)\^\s?/g, ' is not one of `$1`, `$2` **AND** ');
        text = text.replace(/\s?IN(\w+),(\w+),(\w+),(\w+)\^EQ/g, ' is one of `$1`, `$2`, `$3`, `$4`');
        text = text.replace(/\s?IN(\w+),(\w+),(\w+)\^EQ/g, ' is one of `$1`, `$2`, `$3`');
        text = text.replace(/\s?IN(\w+),(\w+)\^EQ/g, ' is one of `$1`, `$2`');
        text = text.replace(/\s?IN(\w+),(\w+),(\w+),(\w+)\^\s?/g, ' is one of `$1`, `$2`, `$3`, `$4` **AND** ');
        text = text.replace(/\s?IN(\w+),(\w+),(\w+)\^\s?/g, ' is one of `$1`, `$2`, `$3` **AND** ');
        text = text.replace(/\s?IN(\w+),(\w+)\^\s?/g, ' is one of `$1`, `$2` **AND** ');
        text = text.replace(/\s?!=(\w+)\^EQ/g, ' is not `$1`');
        text = text.replace(/\s?!=(\w+)\^\s?/g, ' is not `$1` **AND** ');
        text = text.replace(/\s?=(\w+)\^EQ/g, ' is `$1`');
        text = text.replace(/\s?=(\w+)\^\s?/g, ' is `$1` **AND** ');

        text = text.replace(/\s?!=\^EQ/g, ' is not empty');
        text = text.replace(/\s?!=\^\s?/g, ' is not empty **AND** ');
        text = text.replace(/\s?=\^EQ/g, ' is empty');
        text = text.replace(/\s?=\^\s?/g, ' is empty **AND** ');
        return iml ? text : ' ' + text;
    }

    var emptyFuncRe = /^[\r\n\s]*function\s+onCondition\s*\(\s*\)[\r\n\s]*\{[\r\n\s]*\}[\r\n\s]*$/g;
    var idRe = /IO:([a-f\d]{32})/g;

    /**
     * @param {string} filterField
     * @param {string} filterValue
     * @param {({ [key: string]: QuestionItemOld })} varsBySysId
     * @param {({ [key: string]: QuestionItemOld })} varsByName
     * @param {string[]} markdownLines
     * @param {MarkdownGenerationContext} context
     */
    function pushCatalogUiPoliciesSection(filterField, filterValue, varsBySysId, varsByName, markdownLines, context) {
        var policyGr = new GlideRecord('catalog_ui_policy');
        policyGr.addActiveQuery();
        policyGr.addQuery(filterField, filterValue);
        policyGr.orderBy('short_description');
        policyGr.query();
        if (!policyGr.next())
            return;

        markdownLines.push('', '## Catalog UI Policies');
        do {
            markdownLines.push('', '### UI Policy: ' + MarkdownGenerationContext.escapeForMarkdown(policyGr.getValue('short_description')), '');
            /** @type {tyLabeledMultilineStackItem[]} */
            var multiLineStack = [];
            /** @type {(QuestionItemOld | undefined)} */
            var item = undefined;
            if (!gs.nil(policyGr.catalog_conditions)) {
                var catalog_conditions = policyGr.getValue('catalog_conditions');
                var match = idRe.exec(catalog_conditions);
                var decoded = '';
                var startIndex = 0;
                while (match !== null) {
                    if (match.index > startIndex)
                        decoded += catalog_conditions.substring(startIndex, match.index);
                    item = varsBySysId[match[1]];
                    if (item)
                        decoded += '[' + item.question_text + (item.is_set ? '](#variable-set-' : '](#variable-') + item.name + ')';
                    else
                        decoded += match[0];
                    startIndex = idRe.lastIndex;
                    match = idRe.exec(catalog_conditions);
                }
                if (startIndex < catalog_conditions.length)
                    decoded += catalog_conditions.substring(startIndex);
                markdownLines.push("- **Catalog conditions:**" + decodeCatalogConditions(decoded.trim()));
            }
            context.pushListItemIfTrue(policyGr.applies_catalog, markdownLines);
            context.pushListItemIfTrue(policyGr.applies_sc_task, markdownLines);
            context.pushListItemIfTrue(policyGr.applies_req_item, markdownLines);
            context.pushListItemIfTrue(policyGr.on_load, markdownLines);
            context.pushListItemIfTrue(policyGr.reverse_if_false, markdownLines);
            context.pushListItemIfTrue(policyGr.run_scripts, markdownLines);
            if (policyGr.getDisplayValue('run_scripts') == 'true')
                context.pushDisplayValueListItem(policyGr.ui_type, markdownLines, multiLineStack);
            context.pushMultiLineItems(multiLineStack, markdownLines);
            if (!gs.nil(policyGr.description))
                markdownLines.push('', "**Description:**", '', '```text', policyGr.getValue('description'), '```');

            var actionGr = new GlideRecord('catalog_ui_policy_action');
            actionGr.addQuery('ui_policy', policyGr.getUniqueValue());
            actionGr.orderBy('variable');
            actionGr.query();
            if (actionGr.next()) {
                markdownLines.push('', '**Catalog UI Policy Actions:**', '', '| Name | Mandatory | Visible | Read only | Order | Value action |', '| ---- | --------- | ------- | --------- | ----- | ------------ |');
                do {
                    var vn = actionGr.getValue('variable');
                    item = varsByName[vn];
                    // var vn = actionGr.getValue('catalog_variable');
                    var lineText = "| [" + ((typeof item === 'undefined') ? vn : item.question_text) + ((typeof item !== 'undefined' && item.is_set) ? "](#variable-set-" : "](#variable-") + vn + ") | ";
                    switch (actionGr.getValue('mandatory')) {
                        case 'true':
                            lineText += 'True |';
                            break;
                        case 'false':
                            lineText += 'False |';
                            break;
                        default:
                            lineText += 'Leave alone |';
                            break;
                    }
                    switch (actionGr.getValue('visible')) {
                        case 'true':
                            lineText += 'True |';
                            break;
                        case 'false':
                            lineText += 'False |';
                            break;
                        default:
                            lineText += 'Leave alone |';
                            break;
                    }
                    switch (actionGr.getValue('disabled')) {
                        case 'true':
                            lineText += 'True |';
                            break;
                        case 'false':
                            lineText += 'False |';
                            break;
                        default:
                            lineText += 'Leave alone |';
                            break;
                    }
                    if (gs.nil(actionGr.order))
                        lineText += ' |';
                    else
                        lineText += actionGr.getDisplayValue('order') + ' |';
                    if (actionGr.cleared)
                        lineText += "Clear value |";
                    else
                        switch (actionGr.getValue('value_action')) {
                            case 'clear_value':
                                lineText += 'Clear value |';
                                break;
                            case 'set_value':
                                lineText += 'Set value: ' +  MarkdownGenerationContext.escapeForMarkdown(actionGr.getDisplayValue('value')) + ' |';
                                break;
                            default:
                                lineText += 'Leave alone |';
                                break;
                        }
                    markdownLines.push(lineText);
                } while (actionGr.next());
            }

            if (policyGr.getDisplayValue('run_scripts') == 'true') {
                var scriptText;
                if (!gs.nil(policyGr.script_true)) {
                    scriptText = policyGr.getValue('script_true');
                    if (!emptyFuncRe.test(scriptText))
                        markdownLines.push('', '**Execute if true:**', '', '```javascript', scriptText, '```');
                }
                if (!gs.nil(policyGr.script_false)) {
                    scriptText = policyGr.getValue('script_false');
                    if (!emptyFuncRe.test(scriptText))
                        markdownLines.push('', '**Execute if false:**', '', '```javascript', scriptText, '```');
                }
            }
        } while (policyGr.next());
    }

    /**
     * @param {string} filterField
     * @param {string} filterValue
     * @param {({ [key: string]: QuestionItemOld })} varsBySysId
     * @param {string[]} markdownLines
     * @param {MarkdownGenerationContext} context
     */
    function pushCatalogClientScriptsSection(filterField, filterValue, varsBySysId, markdownLines, context) {
        var scriptGr = new GlideRecord('catalog_script_client');
        scriptGr.addActiveQuery();
        scriptGr.addQuery(filterField, filterValue);
        scriptGr.orderBy('name');
        scriptGr.query();
        if (!scriptGr.hasNext())
            return;

        markdownLines.push('', '## Client Scripts');

        while (scriptGr.next()) {
            /** @type {tyLabeledMultilineStackItem[]} */
            var multiLineStack = [];
            markdownLines.push('', '### Client Script: ' + scriptGr.getValue('name'), '');
            context.pushDisplayValueListItem(scriptGr.applies_to, markdownLines, multiLineStack);
            context.pushDisplayValueListItem(scriptGr.ui_type, markdownLines, multiLineStack);
            context.pushDisplayValueListItem(scriptGr.type, markdownLines, multiLineStack);
            if (scriptGr.type == 'onChange' && !gs.nil(scriptGr.cat_variable)) {
                /** @type {(QuestionItemOld | undefined)} */
                var item = undefined;
                var id = scriptGr.getValue('cat_variable');
                if (id.startsWith('IO:') && id.length > 3)
                    item = varsBySysId[id.substring(3)];
                if (item)
                    markdownLines.push("- **Variable name:** [" + item.question_text + (item.is_set ? "](#variable-set-" : "](#variable-") + item.name + ")");
                else
                    markdownLines.push("- **Variable name:** `" + id + "`");
            }
            context.pushDisplayValueListItem(scriptGr.order, markdownLines, multiLineStack);
            context.pushListItemIfTrue(scriptGr.applies_catalog, markdownLines);
            context.pushListItemIfTrue(scriptGr.applies_req_item, markdownLines);
            context.pushListItemIfTrue(scriptGr.applies_sc_task, markdownLines);
            context.pushListItemIfTrue(scriptGr.applies_extended, markdownLines);
            context.pushListItemIfTrue(scriptGr.global, markdownLines);
            context.pushListItemIfFalse(scriptGr.isolate_script, markdownLines);
            context.pushMultiLineItems(multiLineStack, markdownLines);
            if (!gs.nil(scriptGr.description))
                markdownLines.push('', "**Description:**", '', '```text', scriptGr.getValue('description'), '```');
            if (!gs.nil(scriptGr.script))
                markdownLines.push('', "**Script:**", '', '```javascript', scriptGr.getValue('script'), '```');
        }
    }

    /** @typedef {(QuestionItemOld & { field: string })} RecordProducerQuestionItemOld */

    /**
     * @param {(GlideRecord | GlideRecordSecure)} catItemGr - sc_cat_item_producer
     * @param {MarkdownGenerationContext} context
     * @return {string}
     */
    function getRecordProducerMarkdown(catItemGr, context) {
        /** @type {string[]} */
        var markdownLines = ['# "' + MarkdownGenerationContext.escapeForMarkdown(catItemGr.getValue('name')) + '" Record Producer', ''];
        /** @type {tyLabeledMultilineStackItem[]} */
        var multiLineStack = [];
        context.pushTableReferenceListItem(catItemGr.table_name, markdownLines);
        context.pushDisplayValueListItem(catItemGr.short_description, markdownLines, multiLineStack);
        context.pushCodeListItem(catItemGr.description, 'html', markdownLines, multiLineStack);
        context.pushDisplayValueListItem(catItemGr.meta, markdownLines, multiLineStack);
        context.pushDisplayValueListItem(catItemGr.redirect_url, markdownLines, multiLineStack);
        context.pushCodeListItem(catItemGr.script, 'javascript', markdownLines, multiLineStack);
        context.pushImageListItem(catItemGr.icon, markdownLines);
        context.pushImageListItem(catItemGr.picture, markdownLines);
        context.pushDisplayValueListItem(catItemGr.sc_catalogs, markdownLines, multiLineStack);
